-- =====================================================
-- ShopSphere product database - ONE-FILE SETUP (MySQL)
-- Matches the existing schema:
--   categories(id, created_at, description, name, updated_at)
--   products(id, category_id, created_at, description, image_url,
--            name, price, stock_quantity, updated_at)
-- Contains : 9 categories, 55 base products, 722 Myntra products
-- Run ONCE (whole file). It first CLEARS both tables, so it can
-- also be re-run safely without duplicates.
-- =====================================================

SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS shopsphere_product;
USE shopsphere_product;

-- Only creates the tables if they do not exist yet (same columns as yours)
CREATE TABLE IF NOT EXISTS categories (
    id          BIGINT        NOT NULL AUTO_INCREMENT,
    created_at  DATETIME(6),
    description VARCHAR(500),
    name        VARCHAR(100)  NOT NULL,
    updated_at  DATETIME(6),
    PRIMARY KEY (id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS products (
    id             BIGINT         NOT NULL AUTO_INCREMENT,
    category_id    BIGINT         NOT NULL,
    created_at     DATETIME(6),
    description    VARCHAR(2000),
    image_url      VARCHAR(500),
    name           VARCHAR(150)   NOT NULL,
    price          DECIMAL(10,2)  NOT NULL,
    stock_quantity INT            NOT NULL,
    updated_at     DATETIME(6),
    PRIMARY KEY (id),
    KEY idx_products_category (category_id),
    CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories (id)
) ENGINE=InnoDB;

-- Clear old data and reset ids
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE products;
TRUNCATE TABLE categories;
SET FOREIGN_KEY_CHECKS = 1;

-- -----------------------------------------------------
-- categories
-- -----------------------------------------------------

-- -----------------------------------------------------
-- products: base seed (explicit ids 1-8, 15-61)
-- -----------------------------------------------------

-- -----------------------------------------------------
-- products: Myntra (INR prices), ids auto-continue after 61
-- -----------------------------------------------------

-- -----------------------------------------------------
-- Quick check (should show 777 products)
-- -----------------------------------------------------
SELECT c.name, COUNT(*) AS total
FROM products p JOIN categories c ON c.id = p.category_id
GROUP BY c.name;
SELECT COUNT(*) AS total_products FROM products;
