INSERT INTO products (id, category_id, name, description, price, stock_quantity, image_url, created_at, updated_at) VALUES
(1, 6, 'Fjallraven - Foldsack No. 1 Backpack, Fits 15 Laptops', 'Your perfect pack for everyday use and walks in the forest. Stash your laptop (up to 15 inches) in the padded sleeve, your everyday', 109.95, 60, 'https://fakestoreapi.com/img/81fPKd-2AYL._AC_SL1500_t.png', NOW(6), NOW(6)),
(2, 1, 'Mens Casual Premium Slim Fit T-Shirts', 'Slim-fitting style, contrast raglan long sleeve, three-button henley placket, light weight & soft fabric for breathable and comfortable wearing. And Solid stitched shirts with round neck made for durability and a great fit for casual fashion wear and diehard baseball fans. The Henley style round neckline includes a three-button placket.', 22.30, 120, 'https://fakestoreapi.com/img/71-3HjGNDUL._AC_SY879._SX._UX._SY._UY_t.png', NOW(6), NOW(6)),
(3, 1, 'Mens Cotton Jacket', 'Great outerwear jackets for Spring/Autumn/Winter, suitable for many occasions, such as working, hiking, camping, mountain/rock climbing, cycling, traveling or other outdoors. Good gift choice for you or your family member. A warm hearted love to Father, husband or son in this thanksgiving or Christmas Day.', 55.99, 80, 'https://fakestoreapi.com/img/71li-ujtlUL._AC_UX679_t.png', NOW(6), NOW(6)),
(4, 1, 'Mens Casual Slim Fit', 'The color could be slightly different between on the screen and in practice. Please note that body builds vary by person, therefore, detailed size information should be reviewed below on the product description.', 15.99, 150, 'https://fakestoreapi.com/img/71YXzeOuslL._AC_UY879_t.png', NOW(6), NOW(6)),
(5, 4, 'John Hardy Women''s Legends Naga Gold & Silver Dragon Station Chain Bracelet', 'From our Legends Collection, the Naga was inspired by the mythical water dragon that protects the ocean''s pearl. Wear facing inward to be bestowed with love and abundance, or outward for protection.', 695.00, 10, 'https://fakestoreapi.com/img/71pWzhdJNwL._AC_UL640_QL65_ML3_t.png', NOW(6), NOW(6)),
(6, 4, 'Solid Gold Petite Micropave', 'Satisfaction Guaranteed. Return or exchange any order within 30 days. Designed and sold by Hafeez Center in the United States.', 168.00, 25, 'https://fakestoreapi.com/img/61sbMiUnoGL._AC_UL640_QL65_ML3_t.png', NOW(6), NOW(6)),
(7, 4, 'White Gold Plated Princess', 'Classic Created Wedding Engagement Solitaire Diamond Promise Ring for Her. Gifts to spoil your love more for Engagement, Wedding, Anniversary, Valentine''s Day.', 9.99, 200, 'https://fakestoreapi.com/img/71YAIFU48IL._AC_UL640_QL65_ML3_t.png', NOW(6), NOW(6)),
(8, 4, 'Pierced Owl Rose Gold Plated Stainless Steel Double', 'Rose Gold Plated Double Flared Tunnel Plug Earrings. Made of 316L Stainless Steel.', 10.99, 180, 'https://fakestoreapi.com/img/51UDEzMJVpL._AC_UL640_QL65_ML3_t.png', NOW(6), NOW(6)),
(15, 2, 'BIYLACLESEN Women''s 3-in-1 Snowboard Jacket Winter Coats', 'US standard size, please choose size as your usual wear. Material: 100% Polyester; Detachable Liner Fabric: Warm Fleece. Stand collar liner jacket keeps you warm in cold weather. 2 zippered hand pockets, 2 zippered chest pockets and 1 hidden inside pocket. Adjustable and detachable hood and adjustable cuff to prevent wind and water. 3-in-1 detachable design: wear the coat and inner separately or together. Suitable for different seasons and climates.', 56.99, 45, 'https://fakestoreapi.com/img/51Y5NI-I5jL._AC_UX679_t.png', NOW(6), NOW(6)),
(16, 2, 'Lock and Love Women''s Removable Hooded Faux Leather Moto Biker Jacket', '100% polyurethane (shell), 100% polyester (lining), 75% polyester 25% cotton (sweater). Faux leather material for style and comfort. 2 front pockets, 2-for-one hooded denim style faux leather jacket, button detail on waist, detail stitching at sides. Hand wash only, do not bleach, line dry, do not iron.', 29.95, 70, 'https://fakestoreapi.com/img/81XH0e8fefL._AC_UY879_t.png', NOW(6), NOW(6)),
(17, 2, 'Rain Jacket Women Windbreaker Striped Climbing Raincoats', 'Lightweight, perfect for trips or casual wear. Long sleeve with hood and adjustable drawstring waist. Button and zipper front closure, fully striped lining, 2 side pockets. Covers the hips, with a generous hood and adjustable drawstrings.', 39.99, 90, 'https://fakestoreapi.com/img/71HblAHs5xL._AC_UY879_-2t.png', NOW(6), NOW(6)),
(18, 2, 'MBJ Women''s Solid Short Sleeve Boat Neck V', '95% Rayon 5% Spandex. Do not bleach. Lightweight fabric with great stretch for comfort. Ribbed on sleeves and neckline, double stitching on bottom hem.', 9.85, 160, 'https://fakestoreapi.com/img/71z3kpMAYsL._AC_UY879_t.png', NOW(6), NOW(6)),
(19, 2, 'Opna Women''s Short Sleeve Moisture', '100% polyester, machine wash, pre-shrunk for a great fit. Lightweight, roomy and highly breathable moisture-wicking fabric with a comfortable V-neck collar and a slimmer fit for a sleek, feminine silhouette.', 7.95, 220, 'https://fakestoreapi.com/img/51eg55uWmdL._AC_UX679_t.png', NOW(6), NOW(6)),
(20, 2, 'DANVOUY Womens T Shirt Casual Cotton Short', '95% cotton, 5% spandex. Casual short sleeve, letter print, V-neck fashion tee. Soft fabric with some stretch. Suitable for casual, office, beach, school, home and street wear in all seasons.', 12.99, 140, 'https://fakestoreapi.com/img/61pHAEJ4NML._AC_UX679_t.png', NOW(6), NOW(6)),
